def can_transform(k: int, s: str, t: str) -> bool:
    """Return whether insertions, deletions and replacements can turn s into t
    using at most k operations.

    Tracks the furthest reachable source position on each diagonal after each
    edit count, extending every state through a maximal run of equal characters.
    Time is O((len(s) + len(t)) * k + k**2); auxiliary space is O(k).
    """
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False
    if k >= max(n, m):
        return True

    i = 0
    while i < n and i < m and s[i] == t[i]:
        i += 1
    if i == n and i == m:
        return True
    # A diagonal d represents source_index - target_index.
    previous = {0: i}
    for edits in range(1, k + 1):
        current = {}
        for d in range(max(-edits, -m), min(edits, n) + 1):
            best = -1
            # Replace the next character.
            x = previous.get(d, -1)
            if x >= 0 and x < n and x - d < m:
                best = x + 1
            # Delete a source character, moving to diagonal d.
            x = previous.get(d - 1, -1)
            if x >= 0 and x < n:
                best = max(best, x + 1)
            # Insert a target character, moving to diagonal d.
            x = previous.get(d + 1, -1)
            if x >= 0 and x - (d + 1) < m:
                best = max(best, x)
            if best < 0:
                continue
            j = best - d
            while best < n and j < m and s[best] == t[j]:
                best += 1
                j += 1
            if best == n and j == m:
                return True
            current[d] = best
        previous = current
    return False

