from math import isqrt


def count_power_representations(n: int) -> int:
    """Count distinct integers in [1, n] equal to a**b for b >= 2.

    The supported range is 1 <= n <= 10**18. The value 1 is included.

    >>> count_power_representations(99)
    12
    >>> count_power_representations(1000000000000000000)
    1001003332
    """
    limit = n.bit_length() - 1
    mu = [1] * (limit + 1)
    prime = [True] * (limit + 1)
    for p in range(2, limit + 1):
        if prime[p]:
            for multiple in range(p, limit + 1, p):
                mu[multiple] = -mu[multiple]
                if multiple != p:
                    prime[multiple] = False
            for multiple in range(p * p, limit + 1, p * p):
                mu[multiple] = 0

    answer = 1
    for exponent in range(2, limit + 1):
        if mu[exponent] == 0:
            continue
        if exponent == 2:
            root = isqrt(n)
        else:
            low = 1
            high = 1 << ((n.bit_length() + exponent - 1) // exponent)
            while high - low > 1:
                middle = (low + high) // 2
                if middle ** exponent <= n:
                    low = middle
                else:
                    high = middle
            root = low
        # A number whose maximal power exponent is g contributes
        # -sum(mu(d) for d | g, d >= 2), which is 1 exactly when g > 1.
        answer -= mu[exponent] * (root - 1)
    return answer

