from typing import List, Tuple


def max_alkane_vertices(n: int, edges: List[Tuple[int, int]]) -> int:
    """Return the largest subtree whose degrees are 1 or 4, with a degree-4 vertex.

    Return -1 when no such subtree exists. Vertices are numbered 1 through n.
    Runs in O(n) time and space, without recursion.
    """
    adjacency = [[] for _ in range(n + 1)]
    for a, b in edges:
        adjacency[a].append(b)
        adjacency[b].append(a)

    parent = [0] * (n + 1)
    order = [1]
    for vertex in order:
        for neighbor in adjacency[vertex]:
            if neighbor != parent[vertex]:
                parent[neighbor] = vertex
                order.append(neighbor)

    # branch[v] includes v and assumes its edge to its parent is selected.
    # Thus v is either a leaf, or uses exactly three child branches.
    branch = [1] * (n + 1)
    answer = -1
    for vertex in reversed(order):
        largest = []
        for child in adjacency[vertex]:
            if parent[child] == vertex:
                largest.append(branch[child])
                largest.sort(reverse=True)
                if len(largest) > 4:
                    largest.pop()

        if len(largest) >= 3:
            branch[vertex] = 1 + sum(largest[:3])
            if parent[vertex]:
                # The parent may be the topmost leaf of the chosen subtree.
                answer = max(answer, branch[vertex] + 1)
        if len(largest) == 4:
            # Here vertex is the topmost vertex and has four children.
            answer = max(answer, 1 + sum(largest))
    return answer

