from functools import lru_cache


@lru_cache(maxsize=None)
def _count_suffix(remaining: int, digit_sum: int, product: int) -> int:
    """Count completions of a prefix that has already started."""
    if product == 0:
        return 10 ** remaining
    if remaining == 0:
        return int(product % digit_sum == 0)

    # Choosing zero makes every completion beautiful.
    total = 10 ** (remaining - 1)
    for digit in range(1, 10):
        total += _count_suffix(
            remaining - 1, digit_sum + digit, product * digit
        )
    return total


@lru_cache(maxsize=None)
def _count_up_to(bound: int) -> int:
    if bound <= 0:
        return 0

    digits = tuple(map(int, str(bound)))
    total = 0
    # Leading zeros are not digits of the positive integer.
    for length in range(1, len(digits)):
        for first in range(1, 10):
            total += _count_suffix(length - 1, first, first)

    digit_sum = 0
    product = 1
    for position, limit in enumerate(digits):
        remaining = len(digits) - position - 1
        for digit in range(1 if position == 0 else 0, limit):
            total += _count_suffix(
                remaining, digit_sum + digit, product * digit
            )
        digit_sum += limit
        product *= limit

    return total + int(product % digit_sum == 0)


def count_beautiful_numbers(l: int, r: int) -> int:
    """ Count the number of beautiful numbers in the range [l, r] inclusive.

    A positive integer is called beautiful if the product of its digits is divisible by the sum of its digits.

    Args:
        l: The lower bound of the range (inclusive)
        r: The upper bound of the range (inclusive)

    Returns:
        The count of beautiful numbers in the range [l, r]

    Constraints:
        1 <= l <= r < 10^9

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _count_up_to(r) - _count_up_to(l - 1)
